export interface PlayerEpisode {
	id: string;
	number: number;
	name: string;
	still?: Image;
	current: boolean;
}

export enum PlayerSource {
	/** A media file the player reads progressively. */
	File = "file",
	/** An HLS multivariant playlist. */
	Hls = "hls",
}

export interface PlayerSubtitle {
	id: string;
	lang: string;
	label: string;
	url: string;
	forced: boolean;
}

export interface PlayerLoad {
	url: string;
	source: PlayerSource;
	startSeconds: number;
	autoplay: boolean;
	/** Caps an HLS stream at this height (a quality the user pinned); absent to adapt freely. */
	maxHeight?: number;
	/** Sidecar WebVTT tracks the player can show. */
	subtitles: PlayerSubtitle[];
	subtitle?: string;
	/** The embedded audio rendition to start with. */
	audioLang?: string;
	/** A couch follower's player: no seeking or pausing of the shared timeline. */
	linear: boolean;
	/** For the system's Now Playing and lock-screen controls. */
	nowPlaying: NowPlaying;
}

/** The shell's player state. `failed` carries a short reason when the player gave up. */
export interface PlayerReport {
	positionSeconds: number;
	durationSeconds: number;
	playing: boolean;
	buffering?: boolean;
	ended?: boolean;
	failed?: string;
}

export interface PlayerSeason {
	number: number;
	episodes: PlayerEpisode[];
}

export interface PlayerSeek {
	seconds: number;
}

export enum QualityKind {
	/** The source as it is, outside the adaptive ladder. */
	Original = "original",
	/** The ladder, adapting to the connection. */
	Auto = "auto",
	/** One rung of the ladder, pinned. */
	Rendition = "rendition",
}

export interface QualityOption {
	/** What `QualityChosen` takes. */
	key: string;
	kind: QualityKind;
	/** The rendition's height, for its label (`1080p`). */
	height?: number;
}

export interface TrackOption {
	id: string;
	lang: string;
	label: string;
}

export interface PlayerView {
	/**
	 * `loading` while fetching or preparing, `loaded` once the player has a source, `stale`
	 * while a failed player reloads, `notFound`/`failed` with a problem.
	 */
	status: LoadStatus;
	/** What is on screen; absent with the player closed. The web keeps its URL in step. */
	target?: PlayTarget;
	title: string;
	/** The episode's label, empty for a movie. */
	subtitle: string;
	/** The title page to go back to. */
	titleSlug: string;
	backdrop?: Image;
	/** A transcode is being prepared; its progress in percent. */
	preparing?: number;
	qualities: QualityOption[];
	quality: string;
	audio: TrackOption[];
	audioSelected?: string;
	subtitles: TrackOption[];
	subtitleSelected?: string;
	/** The series' playable episodes for the switcher, by season. */
	seasons: PlayerSeason[];
	nextUp?: NextUp;
	/** The series allows random playback, so a shuffle switch makes sense. */
	shuffleAvailable: boolean;
	shuffle: boolean;
	/** A still for the seek-bar preview: append `?t=<seconds>`. */
	frameUrl?: string;
	/** A couch follower's player: hide timeline controls. */
	linear: boolean;
	problem?: Problem;
}

/** A rank tier; `code` is localized by the shell (`rank_tier_<code>`). */
export interface Tier {
	code: string;
	level: number;
	/** `#rrggbb`. */
	colour: string;
	minXp: number;
}

export interface RankBadge {
	tier: Tier;
	/** The tier after this one; the same as `tier` at the top. */
	next: Tier;
	xp: number;
	/** Progress through the current tier, from 0 to 100. */
	percent: number;
}

export interface XpLine {
	/** What earned it; localized by the shell (`rank_xp_source_<key>`). */
	key: string;
	units: number;
	rate: number;
	xp: number;
}

export interface ProfileTotals {
	watchSeconds: number;
	moviesCompleted: number;
	episodesCompleted: number;
	seriesCompleted: number;
	distinctTitles: number;
	distinctGenres: number;
	activeDays: number;
	currentStreak: number;
	longestStreak: number;
	bestDayMinutes: number;
	couchHosted: number;
	couchJoined: number;
	biggestCouch: number;
	emojiSent: number;
}

export interface TopTitle {
	slug: string;
	name: string;
	kind: TitleKind;
	seconds: number;
	poster?: Image;
}

export interface ProfileDetail {
	username: string;
	displayName: string;
	bio: MarkdownDoc;
	avatar?: Image;
	banner?: Image;
	memberSince: string;
	isSelf: boolean;
	public: boolean;
	rank: RankBadge;
	xpTotal: number;
	xpSources: XpLine[];
	achievements: AchievementCard[];
	achievementsWon: number;
	recentUnlocks: AchievementCard[];
	totals: ProfileTotals;
	topTitles: TopTitle[];
	/** Empty when nothing has been watched. */
	favouriteGenre: string;
	/** Watch seconds per hour of the day, 24 entries. */
	hours: number[];
	heatmap: Heatmap;
}

export interface ProfileEdit {
	displayName: string;
	/** Markdown, at most 2000 characters. */
	bio: string;
}

/** Where one save stands: `loading` while it runs, `loaded` once it succeeded. */
export interface SaveState {
	status: LoadStatus;
	problem?: Problem;
}

export interface ProfileEditorView {
	details: SaveState;
	password: SaveState;
	avatar: SaveState;
	banner: SaveState;
}

export interface ProfileView {
	username: string;
	status: LoadStatus;
	profile?: ProfileDetail;
	problem?: Problem;
}

export interface PublicChoice {
	public: boolean;
}

/** A quality from `PlayerView.qualities`, by its key. */
export interface QualityChoice {
	key: string;
}

export interface RankView {
	/** Absent until the first check, or with rankings off. */
	rank?: RankBadge;
	/** Bumped on every genuine level-up, so a badge can pulse once per change. */
	levelUps: number;
	/** The unlock to celebrate now; dismissing it shows the next. */
	celebration?: AchievementCard;
	/** How many more are queued behind it. */
	queued: number;
}

export enum RemoteAction {
	Play = "play",
	Pause = "pause",
	Seek = "seek",
	Next = "next",
	Previous = "previous",
}

export interface RemoteControl {
	action: RemoteAction;
	/** Where to seek; only for `seek`. */
	positionSeconds?: number;
}

/** A screen, panel or piece of state a shell renders from a view model. */
export type Surface = 
	/** Where the app is: which account is active and what the shell should show at the root. */
	| { type: "app", content?: undefined }
	/** The known servers and the add-server flow. */
	| { type: "servers", content?: undefined }
	/** Every account on every server: the "Who's watching?" picker and the account switcher. */
	| { type: "accounts", content?: undefined }
	/** Signing in to a server: password and pairing. */
	| { type: "signIn", content?: undefined }
	/** The signed-in account's devices. */
	| { type: "devices", content?: undefined }
	/** A pairing request this account is approving for another device. */
	| { type: "pairingApproval", content?: undefined }
	/** The active account's session: user, features, display language and theme. */
	| { type: "session", content?: undefined }
	/** A markdown document rendered safely; the content is the source. */
	| { type: "markdown", content: string }
	| { type: "home", content?: undefined }
	/** A listing of movies, series or a genre. */
	| { type: "browse", content: BrowseKey }
	/** A title's detail page; the content is its slug. */
	| { type: "title", content: string }
	| { type: "genres", content?: undefined }
	| { type: "myList", content?: undefined }
	| { type: "search", content?: undefined }
	/** Transient notices for a toast or banner. */
	| { type: "notices", content?: undefined }
	/** The viewer's rank badge and the achievement celebrations. */
	| { type: "rank", content?: undefined }
	/** A member's profile; the content is the username. */
	| { type: "profile", content: string }
	| { type: "leaderboard", content: LeaderboardKey }
	/** The viewer's profile, password and image saves. */
	| { type: "profileEditor", content?: undefined }
	/** The player screen: sources, tracks, qualities, episodes and the next-episode countdown. */
	| { type: "player", content?: undefined }
	/** The couch session: members, reactions, the host's state and the follower's sync. */
	| { type: "couch", content?: undefined };

export interface RenderRequest {
	surfaces: Surface[];
}

export type EffectOutput = 
	| { type: "http", content: HttpResponse }
	/** The request never got an HTTP response (offline, DNS, TLS, timeout). */
	| { type: "httpFailed", content: HttpFailure }
	| { type: "timerFired", content?: undefined }
	/** A store read; `None` when the key holds nothing. */
	| { type: "stored", content: StoredValue }
	/** A store write or delete finished. */
	| { type: "storeDone", content?: undefined }
	| { type: "storeFailed", content: StoreFailure }
	| { type: "socketOpened", content?: undefined }
	/** A text frame from the socket. */
	| { type: "socketText", content: SocketText }
	/** Terminal: the socket closed or could not open. */
	| { type: "socketClosed", content: SocketClosed };

/**
 * The output of an effect the core asked for. Streaming effects (sockets, repeating timers)
 * resolve the same id several times and end with a terminal output.
 */
export interface Resolution {
	nowMs: number;
	id: number;
	output: EffectOutput;
}

export interface SearchText {
	query: string;
}

export interface SearchView {
	query: string;
	status: LoadStatus;
	cards: Card[];
	problem?: Problem;
}

export interface SeasonView {
	id: string;
	number: number;
	name: string;
	overview: string;
	episodes: EpisodeView[];
}

export interface Server {
	id: string;
	/** Base URL without a trailing slash, e.g. `https://media.example.com`. */
	url: string;
	name: string;
	version: string;
	apiLevel: number;
	accent: string;
	/** Plain http: shells mark the server as not encrypted. */
	insecure: boolean;
}

export interface ServerAddress {
	/** What the user typed: a URL, or a host with an optional port. */
	address: string;
}

export interface ServerRef {
	serverId: string;
}

export interface ServersView {
	servers: Server[];
	add: AddServerView;
}

export interface SessionUser {
	username: string;
	displayName: string;
	admin: boolean;
	avatarId?: string;
	bannerId?: string;
	/** Markdown; shells render it through the `Markdown` surface. */
	bio: string;
	/** RFC 3339. */
	createdAt: string;
}

export interface SessionView {
	status: LoadStatus;
	accountId?: string;
	user?: SessionUser;
	features: Features;
	/** The display language for UI strings and catalog text. */
	language: string;
	accent: AccentPalette;
	problem?: Problem;
}

export interface SignInView {
	serverId?: string;
	status: LoadStatus;
	problem?: Problem;
	pairing?: PairingView;
	/** The account that just signed in; the shell moves on. */
	signedIn?: string;
}

export interface SocketClosed {
	/** The WebSocket close code; 1006 when the connection failed. */
	code: number;
	reason?: string;
}

export interface SocketOpen {
	/** `ws://` or `wss://`; a path alone is relative to the page (the web picks the scheme). */
	url: string;
	headers: HttpHeader[];
}

export interface SocketSend {
	/** The id of the open effect. */
	socket: number;
	text: string;
}

export interface SocketText {
	text: string;
}

export interface StoreFailure {
	message: string;
}

export type StoreOp = 
	| { type: "read", content?: undefined }
	| { type: "write", content: string }
	| { type: "delete", content?: undefined };

export interface StoreRequest {
	key: string;
	op: StoreOp;
}

export interface StoredValue {
	value?: string;
}

export interface SubtitleSelection {
	id?: string;
}

export interface TableCell {
	inlines: Inline[];
}

export interface TableRow {
	cells: TableCell[];
}

export interface TableBlock {
	header: TableCell[];
	rows: TableRow[];
}

export interface TimerRequest {
	afterMs: number;
	/** Fire again every `after_ms` until cancelled. */
	repeat?: boolean;
}

/** The highest resolution a title is available in. */
export enum Quality {
	Sd = "sd",
	Hd720 = "hd720",
	Hd1080 = "hd1080",
	Uhd = "uhd",
}

export interface TitleDetailView {
	id: string;
	slug: string;
	name: string;
	kind: TitleKind;
	year?: number;
	overview: string;
	genres: string[];
	contentRating?: string;
	runtimeMinutes?: number;
	poster?: Image;
	backdrop?: Image;
	logo?: Logo;
	/** The page's colours, from the backdrop. */
	accent?: AccentPalette;
	quality?: Quality;
	hdr: boolean;
	inList: boolean;
	/** Absent for a series without a playable episode. */
	play?: PlayAction;
	/** A series that allows playing a random episode. */
	shuffle: boolean;
	/** Only seasons and episodes that have something to play. */
	seasons: SeasonView[];
}

export interface TitleView {
	slug: string;
	status: LoadStatus;
	detail?: TitleDetailView;
	problem?: Problem;
}

/** A track by id; no id turns subtitles off. */
export interface TrackChoice {
	id?: string;
}

export interface UploadRequest {
	/** The request without a body; the shell sends the form as its body. */
	request: HttpRequest;
	/** The handle the shell gave the core for the picked file. */
	file: string;
	/**
	 * The form part the file goes in, with the file's own name (servers type images by its
	 * extension).
	 */
	field: string;
}

export interface UserCode {
	code: string;
}

export interface WatchlistChange {
	titleId: string;
	/** True to add the title to My List, false to remove it. */
	listed: boolean;
}

export type PlayerCommand = 
	/**
	 * Replace what is playing. Sent again for a quality or audio-file switch, starting where
	 * playback was.
	 */
	| { type: "load", content: PlayerLoad }
	| { type: "play", content?: undefined }
	| { type: "pause", content?: undefined }
	| { type: "seek", content: PlayerSeek }
	/** Switch to the stream's embedded audio rendition in this language. */
	| { type: "selectAudio", content: AudioRendition }
	/** Show this subtitle track, or none. */
	| { type: "selectSubtitles", content: SubtitleSelection }
	/** Stop and release the player. */
	| { type: "stop", content?: undefined };

export type SocketCommand = 
	| { type: "open", content: SocketOpen }
	| { type: "send", content: SocketSend }
	| { type: "close", content: EffectRef };

